// Authored fictional practice cases. These are exercises, not claims about the owner.
export const LEVELS = ["Foundation", "Applied", "Advanced", "Boardroom"];
const levels = ["Foundation", "Applied", "Applied", "Advanced", "Boardroom"];
function cases(domain, rows) {
  return rows.map(([id, title, role, prompt, cue], i) => ({ id, title, role, prompt, cue, domain, skill: domain, level: levels[Math.min(i, 4)], minutes: i < 3 ? 5 : 8 }));
}
