export const STORY_ASSIGNMENTS = MISSIONS.flatMap(([domain, rows]) => rows.map(([id,title,context,story], i) => ({
  id:`story-${id}`,title,domain,skill:domain,level:levels[i],minutes:8,
  formatId:["recommendation","insight","pitch","leadership","recommendation"][i],
  audience:i===0||i===4?"MD / board":"Product leaders",
  prompt:`Fictional practice context: ${context} Writing assignment: ${story} If you use your own experience, anonymise it and distinguish observed outcomes from hypotheses.`,
  cue:"Make the decision, evidence and trade-off clear. Use only outcomes you can substantiate.",
})));
export const RECORDING_ASSIGNMENTS = MISSIONS.flatMap(([domain, rows]) => rows.map(([id,title,context,_story,recording], i) => ({
  id:`recording-${id}`,title,domain,skill:domain,level:levels[i],minutes:10,
  seconds:[60,90,90,180,180][i],audience:i===0?"General audience":i===4?"MD / board":"Product leaders",
  prompt:`Fictional practice context: ${context} Recording assignment: ${recording} Keep the delivery natural; use your own words rather than memorising a polished script.`,
  cue:"Rehearse one clear opening, one supporting example and one useful closing. Self-review your delivery while AI reviews the transcript.",
})));
